pages.css:
.cover{height:100%;box-sizing:border-box;position:relative;overflow:hidden;
 background:linear-gradient(160deg,#1a1a2e 0%,#242449 55%,#E2571C 230%);
 font-family:'Poppins','Segoe UI',Arial,sans-serif;color:#fff;
 display:flex;flex-direction:column;justify-content:space-between;padding:56px 54px 44px;}
.cov-shape1{position:absolute;top:-90px;right:-90px;width:320px;height:320px;border-radius:50%;background:rgba(245,166,35,0.18);}
.cov-shape2{position:absolute;bottom:-120px;left:-80px;width:380px;height:380px;border-radius:50%;background:rgba(255,255,255,0.06);}
.cov-shape3{position:absolute;top:280px;right:60px;width:120px;height:120px;border-radius:24px;transform:rotate(18deg);background:rgba(245,166,35,0.14);}
.cov-eyebrow{font-size:17.5px;font-weight:800;letter-spacing:3px;color:#F5A623;text-transform:uppercase;position:relative;z-index:2;}
.cov-series{font-size:44px;font-weight:800;margin-top:6px;letter-spacing:1px;position:relative;z-index:2;}
.cov-subject{font-size:26px;font-weight:700;color:#F5A623;margin-top:14px;position:relative;z-index:2;}
.cov-grade{display:inline-block;margin-top:18px;background:#F5A623;color:#1a1a2e;font-weight:800;font-size:26px;padding:8px 22px;border-radius:30px;position:relative;z-index:2;}
.cov-footer{position:relative;z-index:2;border-top:1px solid rgba(255,255,255,0.25);padding-top:18px;}
.cov-author{font-size:17px;font-weight:700;}
.cov-inst{font-size:16.5px;color:rgba(255,255,255,0.75);margin-top:3px;}

.wb-shell{height:100%;box-sizing:border-box;padding:16px 20px 14px;display:flex;
 flex-direction:column;gap:10px;font-family:'Poppins','Segoe UI',Arial,sans-serif;
 color:#1a1a1a;background:#ffffff;}
.wb-topbar{display:flex;align-items:center;justify-content:space-between;gap:10px;}
.wb-patbadge{display:inline-flex;align-items:center;gap:6px;background:#1a1a2e;color:#fff;
 font-weight:800;font-size:13px;letter-spacing:.5px;text-transform:uppercase;
 padding:5px 12px;border-radius:20px;}
.wb-stagebadge{display:inline-flex;align-items:center;gap:7px;background:#4755691A;
 border:2px solid #475569;color:#475569;font-weight:800;font-size:13px;
 padding:4px 12px;border-radius:20px;}
.wb-progress{display:flex;gap:5px;margin-top:2px;}
.wb-dot{flex:1;height:7px;border-radius:4px;background:#E5E7EB;}
.wb-dot.done{background:#475569;}
.wb-pagetitle{font-size:25px;font-weight:800;color:#1a1a2e;border-bottom:3px solid #475569;
 padding-bottom:6px;margin:2px 0 0;}
.wb-para{font-size:15.5px;line-height:1.55;font-weight:500;color:#1a1a1a;margin:0;}
.wb-body{flex:1;overflow:hidden;display:flex;flex-direction:column;gap:10px;}
.wb-chiplist{display:flex;flex-wrap:wrap;gap:8px;}
.wb-chip{background:#47556914;border:1.5px solid #47556955;color:#1a1a1a;
 font-weight:700;font-size:14px;padding:6px 12px;border-radius:9px;}
.wb-table{border-collapse:collapse;font-size:14.5px;}
.wb-table td{padding:6px 8px;border-bottom:1px solid #E5E7EB;vertical-align:top;}
.wb-word{font-weight:800;color:#475569;white-space:nowrap;}
.wb-bullets{margin:0;padding-left:20px;font-size:15px;line-height:1.7;}
.wb-bullets li{margin-bottom:3px;}
.wb-blank{color:#475569;font-weight:700;}
.wb-sortcols{display:flex;gap:14px;}
.wb-sortcol{flex:1;border:2px dashed #47556955;border-radius:10px;padding:8px 10px;}
.wb-sortcol h4{margin:0 0 6px;font-size:14px;color:#475569;}
.wb-footer{display:flex;justify-content:space-between;font-size:11.5px;color:#6B7280;
 border-top:1px solid #E5E7EB;padding-top:6px;}
.wb-hint{font-size:13px;color:#6B7280;font-style:italic;}

